from rules import SOLVERS


def solve(data):
    return {component_id: solver(data[component_id])
            for component_id, solver in SOLVERS.items()}

def ledger_solver(revision_first, discounted):
    def solve(data):
        cutoff = data.get("cutoff", 10**9)
        chosen = {}
        for position, event in enumerate(data["events"]):
            sequence = event.get("sequence", 0)
            if sequence > cutoff:
                continue
            event_id = event.get("id", "anonymous:" + str(position))
            if revision_first:
                key = (event.get("revision", 0), position)
            else:
                key = (sequence, event.get("revision", 0), position)
            if event_id not in chosen or key > chosen[event_id][0]:
                chosen[event_id] = (key, event)

        balances = dict(data.get("opening", {}))
        mode = data["rounding"]

        def rounded(n, d=10000):
            if mode == "half_up":
                return (n + d // 2) // d
            return n // d

        for _, event in chosen.values():
            if event.get("void", False):
                continue
            raw = event["price"] * event.get("quantity", 1)
            discount = min(10000, max(0, event.get("discount_bp", 0)))
            net = rounded(raw * (10000 - discount))
            base = net if discounted else raw
            tax = rounded(base * event.get("tax_bp", 0))
            total = net + tax
            if event.get("kind") == "refund":
                total = -total
            key = event.get("account", "default") + "|" + event.get("currency", "USD")
            balances[key] = balances.get(key, 0) + total
        return {"balances": balances}
    return solve


def dependency_solver(data):
    packages = data["packages"]
    names = sorted(packages)
    features = set(data.get("features", []))
    blocked = data.get("blocked", {})
    pins = data.get("pins", {})
    roots = data["roots"]
    rows = {name: {row["version"]: row for row in versions}
            for name, versions in packages.items()}
    best_vector = None
    best = None

    # Enumerating all assignments also allows absent packages, represented by -1.
    def check(assignment):
        installed = {name for name in names if assignment[name] != -1}
        for name, bounds in roots.items():
            version = assignment[name]
            if version == -1 or not bounds[0] <= version <= bounds[1]:
                return False
        for name in installed:
            version = assignment[name]
            if version in blocked.get(name, ()):
                return False
            if name in pins and version != pins[name]:
                return False

        edges = {name: [] for name in installed}
        for name in installed:
            row = rows[name][assignment[name]]
            for dep in row.get("deps", []):
                feature = dep.get("feature", "")
                if feature and feature not in features:
                    continue
                other = dep["name"]
                version = assignment[other]
                if version == -1 or not dep["min"] <= version <= dep["max"]:
                    return False
                edges[name].append(other)

        # Only packages reachable through active dependencies of roots may be installed.
        reachable = set()
        stack = list(roots)
        while stack:
            name = stack.pop()
            if name in reachable:
                continue
            reachable.add(name)
            stack.extend(edges[name])
        if reachable != installed:
            return False

        active, finished = set(), set()
        def visit(name):
            if name in active:
                return False
            if name in finished:
                return True
            active.add(name)
            if any(not visit(other) for other in edges[name]):
                return False
            active.remove(name)
            finished.add(name)
            return True
        return all(visit(name) for name in installed)

    def search(index, assignment):
        nonlocal best_vector, best
        if index == len(names):
            if not check(assignment):
                return
            vector = tuple(assignment[name] for name in names)
            if best_vector is None or vector > best_vector:
                best_vector = vector
                best = {name: assignment[name] for name in names if assignment[name] != -1}
            return
        name = names[index]
        # Higher versions first; -1 is lexicographically below every valid version.
        options = sorted(rows[name], reverse=True) + [-1]
        for version in options:
            assignment[name] = version
            search(index + 1, assignment)

    search(0, {})
    if best is None:
        return {"error": "unsatisfiable"}
    return {"versions": best}


def quota_solver(data):
    from itertools import combinations

    jobs = data["jobs"]
    k = data["k"]
    blocked = set(data.get("blocked", []))
    mandatory = set(data.get("mandatory", []))
    quotas = data.get("quotas", {})
    available = [job for job in jobs if job["id"] not in blocked]
    best_value = None
    best_ids = None

    for subset in combinations(available, k):
        ids = {job["id"] for job in subset}
        if not mandatory.issubset(ids):
            continue
        counts = {}
        for job in subset:
            counts[job["group"]] = counts.get(job["group"], 0) + 1
        if any(not low <= counts.get(group, 0) <= high
               for group, (low, high) in quotas.items()):
            continue
        events = []
        for job in subset:
            events.append((job["start"], 1))
            events.append((job["end"], -1))
        active = 0
        valid = True
        for _, change in sorted(events):  # end (-1) precedes start at shared endpoint
            active += change
            if active > 2:
                valid = False
                break
        if not valid:
            continue
        value = sum(job["value"] for job in subset)
        selected = sorted(ids)
        if (best_value is None or value > best_value or
                (value == best_value and selected < best_ids)):
            best_value, best_ids = value, selected

    if best_value is None:
        return {"error": "impossible"}
    return {"selected": best_ids, "value": best_value}


def route_solver(data):
    import heapq

    required = data.get("required", [])
    required_bit = {node: 1 << i for i, node in enumerate(required)}
    full = (1 << len(required)) - 1
    source = data["source"]
    start_mask = required_bit.get(source, 0)
    initial = (source, start_mask, data["coupons"])
    distances = {initial: data["start"]}
    queue = [(data["start"], source, start_mask, data["coupons"])]
    graph = [[] for _ in range(data["n"])]
    for edge in data["edges"]:
        graph[edge["u"]].append(edge)

    while queue:
        time, node, mask, coupons = heapq.heappop(queue)
        state = (node, mask, coupons)
        if distances.get(state) != time:
            continue
        if node == data["target"] and mask == full:
            return {"arrival": time}
        for edge in graph[node]:
            depart = max(time, edge["open"])
            if depart >= edge["close"]:
                continue
            choices = [(edge["duration"], coupons)]
            if coupons:
                duration = max(2, edge["duration"] - edge.get("discount", 0))
                choices.append((duration, coupons - 1))
            for duration, left in choices:
                arrival = depart + duration
                if arrival > data["deadline"]:
                    continue
                nxt = edge["v"]
                next_mask = mask | required_bit.get(nxt, 0)
                next_state = (nxt, next_mask, left)
                if arrival < distances.get(next_state, float("inf")):
                    distances[next_state] = arrival
                    heapq.heappush(queue, (arrival, nxt, next_mask, left))
    return {"arrival": None}


SOLVERS = {
    "component_01": ledger_solver(True, True),
    "component_02": ledger_solver(False, True),
    "component_03": ledger_solver(True, False),
    "component_04": ledger_solver(False, False),
    "component_05": ledger_solver(True, True),
    "component_06": dependency_solver,
    "component_07": quota_solver,
    "component_08": route_solver,
}
